// Anvil Handbook — client application.
// Reads window.ANVIL (generated by build.mjs) and renders the handbook as a hash-routed single page:
//   #/                     overview and build plan
//   #/doc/<id>[/<anchor>]  one document
//   #/diagrams[?kind=X]    diagram gallery
//   #/diagram/<name>       zoomable diagram viewer
(() => {
  'use strict';

  const DATA = window.ANVIL;
  const $ = (sel, root = document) => root.querySelector(sel);
  const $$ = (sel, root = document) => [...root.querySelectorAll(sel)];
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

  const main = $('#main');
  if (!DATA) {
    main.innerHTML = '<div class="empty">The handbook content is missing. Run <code>npm --prefix site run build</code> to generate <code>content.js</code>.</div>';
    return;
  }

  const docs = DATA.docs;
  const docsById = new Map(docs.map((d) => [d.id, d]));
  const docsByCode = new Map(docs.filter((d) => d.docId).map((d) => [d.docId, d]));
  const diagrams = DATA.diagrams;
  const diagramsByName = new Map(diagrams.map((d) => [d.name, d]));
  const diagramsByCode = new Map(diagrams.map((d) => [d.code, d]));

  /* ------------------------------------------------------------------ data */

  // Phases from ANV-SPMP-001 §3.3. Weeks are counted from Mon 26 Oct 2026 (start of P0).
  const PLAN_START = new Date(Date.UTC(2026, 9, 26));
  const PLAN_WEEKS = 28;
  const PHASES = [
    { id: 'P0', name: 'Requirements & design', start: 0, weeks: 1, done: true, dates: 'done 30 Oct 2026', focus: 'SRS, SDD with UML, test plan, project plan, traceability', exit: 'SRS / SDD / STP / SPMP / RTM approved', tests: '—' },
    { id: 'P1', name: 'Foundation', start: 1, weeks: 2, dates: '2 – 15 Nov 2026', focus: 'Config, logging, database + migrations, HTTP server, event bus, task queue, dev tooling, project CI on both OSes', exit: '`anvil init && anvil serve` works on Windows and Linux; CI green on both', tests: 'TC-SMK-01, TC-ADM-04, TC-ADM-07' },
    { id: 'P2', name: 'Identity & access', start: 3, weeks: 2, dates: '16 – 29 Nov 2026', focus: 'Users, argon2id passwords, sessions + CSRF, personal access tokens, permission evaluation, login UI', exit: 'Login, tokens and permissions work; security tests pass', tests: 'TC-AUTH-01 … TC-AUTH-13' },
    { id: 'P3', name: 'Git hosting & browsing', start: 5, weeks: 4, dates: '30 Nov – 27 Dec 2026', focus: 'git command wrapper, smart HTTP clone/push, server hooks, branch protection, file/commit/diff browsing', exit: 'Clone, push, protection and browsing work on both OSes; 1 GB repository', tests: 'TC-REPO-01 … TC-REPO-19' },
    { id: 'P4', name: 'Issues & pull requests', start: 9, weeks: 4, dates: '28 Dec 2026 – 24 Jan 2027', focus: 'Issues, labels, comments, pull requests, mergeability via merge-tree, review, merge + squash with compare-and-swap', exit: 'Full PR flow including conflicts and concurrent merges', tests: 'TC-COL-01 … TC-COL-11' },
    { id: 'P5', name: 'CI engine & runner', start: 13, weeks: 6, dates: '25 Jan – 7 Mar 2027', focus: 'GitHub + GitLab parsers, trigger, scheduler, runner API, live logs, secrets; anvil-runner with PowerShell/bash and process-tree control', exit: 'Demo pipeline passes in both formats on both OSes; Anvil builds itself', tests: 'TC-CI-01 … TC-CI-28' },
    { id: 'P6', name: 'Publishing', start: 19, weeks: 3, dates: '8 – 28 Mar 2027', focus: 'Artifacts + blob store, releases, generic package registry, deployments, demo app with deploy scripts', exit: 'Tag → multi-OS build → release → manual deploy', tests: 'TC-PUB-01 … TC-PUB-09' },
    { id: 'P7', name: 'Architecture Explorer', start: 22, weeks: 3, dates: '29 Mar – 18 Apr 2027', focus: 'Trace spans across server, hooks, queue and runner; live diagram, replay, guided tours', exit: 'A push is traced end to end in the Explorer', tests: 'TC-EXP-01 … TC-EXP-05' },
    { id: 'P8', name: 'Hardening & release 1.0', start: 25, weeks: 3, dates: '19 Apr – 9 May 2027', focus: 'Backup/restore, metrics, performance, fuzzing, accessibility, install verification, packaging', exit: 'All release criteria in the test plan met; v1.0 released by Anvil’s own pipeline', tests: 'Full regression, TC-NFR-01 … TC-NFR-14' },
  ];
  const MILESTONES = [
    { id: 'M1', name: 'Docs approved', week: 1 },
    { id: 'M3', name: 'Anvil hosts its own Git', week: 9 },
    { id: 'M5', name: 'Anvil runs its own CI', week: 19 },
    { id: 'M8', name: 'Release 1.0', week: 28 },
  ];

  const PROCESS = [
    { title: 'Specify', doc: 'srs', text: 'Every feature and quality target becomes a numbered requirement with a priority and a use case.' },
    { title: 'Design', doc: 'sdd', text: 'Each requirement is answered by a module, an interface and a UML diagram, viewpoint by viewpoint.' },
    { title: 'Plan the tests', doc: 'stp', text: 'Every requirement gets test cases that must pass on Windows and on Linux.' },
    { title: 'Build in phases', doc: 'spmp', text: 'Nine phases, each ending with a working, demoable increment and its exit criteria.' },
    { title: 'Trace and verify', doc: 'rtm', text: 'The matrix links requirement → design → test, so nothing is built untested or tested unbuilt.' },
  ];

  /** Counts distinct matches of re in a document's HTML (used for the live facts on the overview). */
  function countDistinct(docId, re) {
    const doc = docsById.get(docId);
    return doc ? new Set(doc.html.match(re) || []).size : 0;
  }

  /* ------------------------------------------------------------------ sidebar */

  function renderSidebar() {
    const formal = docs.filter((d) => d.group === 'formal');
    const refs = docs.filter((d) => d.group === 'reference');
    const item = (d) => `<li><a href="#/doc/${d.id}" data-doc="${d.id}"><span class="nav-code">${esc(d.short)}</span><span>${esc(d.title)}</span></a></li>`;
    $('#sidebar-nav').innerHTML = `
      <nav class="nav-group" aria-label="Start">
        <ul class="nav-list simple">
          <li><a href="#/" data-view="home">Overview &amp; build plan</a></li>
          <li><a href="#/diagrams" data-view="diagrams">Diagram catalogue (${diagrams.length})</a></li>
        </ul>
      </nav>
      <nav class="nav-group" aria-label="Formal documents">
        <div class="nav-label">Formal documents</div>
        <ul class="nav-list">${formal.map(item).join('')}</ul>
      </nav>
      <nav class="nav-group" aria-label="Reference annexes">
        <div class="nav-label">Reference annexes</div>
        <ul class="nav-list">${refs.map(item).join('')}</ul>
      </nav>`;
  }

  function markCurrent(route) {
    $$('#sidebar-nav a').forEach((a) => {
      const on = (a.dataset.doc && route.view === 'doc' && a.dataset.doc === route.id)
        || (a.dataset.view === 'home' && route.view === 'home')
        || (a.dataset.view === 'diagrams' && (route.view === 'diagrams' || route.view === 'diagram'));
      if (on) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
    });
    const section = route.view === 'home' ? 'home'
      : route.view === 'diagrams' || route.view === 'diagram' ? 'diagrams'
      : route.view === 'doc' ? (docsById.get(route.id)?.group === 'reference' ? 'reference' : 'formal') : '';
    $$('.topnav a').forEach((a) => a.setAttribute('aria-current', String(a.dataset.nav === section)));
  }

  /* ------------------------------------------------------------------ router */

  function parseRoute() {
    const raw = decodeURIComponent(location.hash.replace(/^#\/?/, ''));
    const [pathPart, query = ''] = raw.split('?');
    const parts = pathPart.split('/').filter(Boolean);
    const params = new URLSearchParams(query);
    if (parts[0] === 'doc' && docsById.has(parts[1])) return { view: 'doc', id: parts[1], anchor: parts.slice(2).join('/') };
    if (parts[0] === 'diagrams') return { view: 'diagrams', kind: params.get('kind') || '' };
    if (parts[0] === 'diagram' && diagramsByName.has(parts[1])) return { view: 'diagram', name: parts[1] };
    return { view: 'home' };
  }

  let current = null;
  let spy = null;

  function route() {
    const r = parseRoute();
    closeDrawer();
    markCurrent(r);
    // Same document, different section: scroll only.
    if (current && r.view === 'doc' && current.view === 'doc' && current.id === r.id) {
      current = r;
      scrollToAnchor(r.anchor);
      return;
    }
    current = r;
    if (spy) { spy.disconnect(); spy = null; }
    if (r.view === 'doc') renderDoc(r);
    else if (r.view === 'diagrams') renderGallery(r);
    else if (r.view === 'diagram') renderDiagram(r);
    else renderHome();
    document.title = titleFor(r);
  }

  function titleFor(r) {
    if (r.view === 'doc') return `${docsById.get(r.id).short} · ${docsById.get(r.id).title} — Anvil Handbook`;
    if (r.view === 'diagram') return `${diagramsByName.get(r.name).code} ${diagramsByName.get(r.name).title} — Anvil Handbook`;
    if (r.view === 'diagrams') return 'Diagrams — Anvil Handbook';
    return 'Anvil Handbook';
  }

  function scrollToAnchor(anchor) {
    const el = anchor && document.getElementById(anchor);
    if (el) el.scrollIntoView({ block: 'start' });
    else window.scrollTo(0, 0);
  }

  /* ------------------------------------------------------------------ home */

  function renderHome() {
    const fr = countDistinct('srs', /\bFR-[A-Z]+-\d\d\b/g);
    const nfr = countDistinct('srs', /\bNFR-[A-Z]+-\d\d\b/g);
    const uc = countDistinct('srs', /\bUC-(?:1[0-2]|[1-9])\b/g);
    const tc = countDistinct('stp', /\bTC-[A-Z]+-\d\d\b/g);
    const formal = docs.filter((d) => d.group === 'formal');

    main.innerHTML = `
      <div class="home">
        <section class="hero" aria-labelledby="hero-title">
          <p class="hero-meta"><span>Engineering handbook</span><span>Planning baseline v1.0</span><span>30 Oct 2026</span></p>
          <h1 id="hero-title">Anvil</h1>
          <p class="hero-lede">A self-hosted code forge with <strong>GitHub-style collaboration</strong> and <strong>GitLab-style CI/CD</strong>, written from scratch to run natively on <strong>Windows and Linux</strong> without Docker. This handbook holds everything decided before the first line of code: what it must do, how it is designed, how it will be tested, and the order it will be built in.</p>
          <div class="hero-actions">
            <a class="btn primary" href="#/doc/srs">Start with the requirements</a>
            <a class="btn" href="#/diagrams">Browse ${diagrams.length} diagrams</a>
          </div>
          <div class="facts" aria-label="Baseline at a glance">
            <div class="fact"><b>${fr}</b><span>functional requirements</span></div>
            <div class="fact"><b>${nfr}</b><span>quality requirements</span></div>
            <div class="fact"><b>${uc}</b><span>use cases</span></div>
            <div class="fact"><b>${tc}</b><span>test cases</span></div>
            <div class="fact"><b>${PLAN_WEEKS}</b><span>weeks to release 1.0</span></div>
          </div>
        </section>

        <section aria-labelledby="process-title">
          <div class="section-head">
            <p class="eyebrow">How Anvil gets built</p>
            <h2 id="process-title">Five documents, one chain of evidence</h2>
            <p>Each step produces a formal document that the next one builds on. Read them in this order to see how a requirement turns into code that is proven to work.</p>
          </div>
          <ol class="process">
            ${PROCESS.map((p, i) => {
              const d = docsById.get(p.doc);
              return `<li><span class="step-no">Step ${i + 1}</span><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p><a class="doc-chip" href="#/doc/${d.id}">${esc(d.short)} · ${esc(d.docId)}</a></li>`;
            }).join('')}
          </ol>
        </section>

        <section aria-labelledby="plan-title">
          <div class="section-head">
            <p class="eyebrow">Build plan · from ${esc(docsById.get('spmp').docId)}</p>
            <h2 id="plan-title">Nine phases, each ending in something that works</h2>
            <p>Bars are drawn to scale in weeks for one full-time developer. Select a phase to see what it delivers and the test cases that close it.</p>
          </div>
          ${planHtml()}
        </section>

        <section aria-labelledby="register-title">
          <div class="section-head">
            <p class="eyebrow">Document register</p>
            <h2 id="register-title">The formal set</h2>
            <p>Written to IEEE and ISO/IEC/IEEE standards. The reference annexes below them hold protocol, API, schema and function-level detail.</p>
          </div>
          <div class="register">
            ${formal.map((d) => `
              <a class="reg-card" href="#/doc/${d.id}">
                <div class="reg-top"><span class="reg-short">${esc(d.short)}</span><span class="reg-id">${esc(d.docId)}</span></div>
                <h3>${esc(d.title)}</h3>
                <p>${esc(d.summary)}</p>
                <div class="reg-foot">${esc(d.standard)} · v1.0 · Draft for approval</div>
              </a>`).join('')}
            <a class="reg-card" href="#/doc/ref-index">
              <div class="reg-top"><span class="reg-short">REF</span><span class="reg-id">ANV-REF-001</span></div>
              <h3>Technical reference annexes</h3>
              <p>${docs.filter((d) => d.group === 'reference').length - 1} annexes: Git internals, API, data model, CI/CD engine, security, cross-platform rules, onboarding, module reference.</p>
              <div class="reg-foot">Supporting detail</div>
            </a>
          </div>
        </section>

        <section aria-labelledby="arch-title">
          <div class="section-head">
            <p class="eyebrow">Architecture at a glance</p>
            <h2 id="arch-title">One server binary, any number of runners</h2>
          </div>
          <div class="arch-preview">
            <a class="diagram-figure" href="#/diagram/CP-01-server-components">
              <img src="diagrams/CP-01-server-components.svg" alt="CP-01 anvil server components" loading="lazy">
              <span class="diagram-tag">CP-01 · Component</span>
            </a>
            <div class="arch-notes">
              <p><strong>Modular monolith.</strong> The <code>anvil</code> server is one Go executable in three layers: transport, services, infrastructure. Only one package runs git, and only one runs SQL.</p>
              <p><strong>Real Git underneath.</strong> Clones and pushes are handled by the standard <code>git</code> program. Server hooks call back into Anvil to enforce branch protection and start pipelines.</p>
              <p><strong>Runners pull work.</strong> <code>anvil-runner</code> long-polls over HTTPS and runs steps in PowerShell or bash, so it works behind firewalls on either OS.</p>
              <p><a href="#/doc/sdd">Read the full design →</a></p>
            </div>
          </div>
        </section>
      </div>`;

    $$('.plan-row', main).forEach((row) => row.addEventListener('click', () => togglePhase(row)));
    window.scrollTo(0, 0);
  }

  function planHtml() {
    const pct = (w) => `${(w / PLAN_WEEKS) * 100}%`;
    // Month ticks positioned by real dates.
    const ticks = [];
    for (let m = 0; m < 8; m++) {
      const d = new Date(Date.UTC(2026, 10 + m, 1));
      const week = (d - PLAN_START) / (7 * 864e5);
      if (week > 0 && week < PLAN_WEEKS) {
        const label = d.toLocaleDateString('en-GB', { month: 'short', timeZone: 'UTC' }) + (d.getUTCMonth() === 0 ? ` ${d.getUTCFullYear()}` : '');
        ticks.push(`<span style="left:${pct(week)}">${label}</span>`);
      }
    }
    const rows = PHASES.map((p, i) => `
      <button class="plan-row" type="button" aria-expanded="false" aria-controls="phase-${p.id}">
        <span class="plan-label"><b>${p.id}</b><span>${esc(p.name)}</span></span>
        <span class="plan-track"><span class="plan-bar${p.done ? ' done' : ''}" style="left:${pct(p.start)};width:${pct(p.weeks)};background-color:var(--t${i})"></span></span>
        <span class="plan-weeks">${p.weeks} wk</span>
      </button>
      <div class="plan-detail" id="phase-${p.id}" hidden>
        <dl>
          <dt>Dates</dt><dd>${esc(p.dates)}</dd>
          <dt>Delivers</dt><dd>${esc(p.focus)}</dd>
          <dt>Done when</dt><dd>${inlineCode(p.exit)}</dd>
          <dt>Closing tests</dt><dd>${esc(p.tests)}</dd>
        </dl>
      </div>`).join('');
    return `
      <div class="plan">
        <div class="plan-scale" aria-hidden="true"><div>Phase</div><div class="scale-track">${ticks.join('')}</div><div></div></div>
        ${rows}
        <div class="milestones">${MILESTONES.map((m) => `<span class="milestone"><b>${m.id}</b> ${esc(m.name)} · week ${m.week}</span>`).join('')}</div>
        <div class="temper-legend"><span class="temper-strip">${PHASES.map((_, i) => `<i style="background:var(--t${i})"></i>`).join('')}</span>Phase colours follow the oxide colours of tempered steel, from straw to blue.</div>
      </div>`;
  }

  const inlineCode = (s) => esc(s).replace(/`([^`]+)`/g, '<code>$1</code>');

  function togglePhase(row) {
    const open = row.getAttribute('aria-expanded') === 'true';
    row.setAttribute('aria-expanded', String(!open));
    document.getElementById(row.getAttribute('aria-controls')).hidden = open;
  }

  /* ------------------------------------------------------------------ document */

  function renderDoc(r) {
    const doc = docsById.get(r.id);
    const idx = docs.indexOf(doc);
    const prev = docs[idx - 1];
    const next = docs[idx + 1];

    const cells = doc.group === 'formal'
      ? [['Document ID', doc.docId], ['Standard', doc.standard], ['Version', '1.0'], ['Status', '<span class="status-pill">Draft for approval</span>'], ['Date', '30 Oct 2026']]
      : [['Annex', doc.short === 'Index' ? 'Index' : `${doc.short} of 17`], ['Part of', 'ANV-REF-001'], ['Role', 'Supporting detail'], ['Date', '30 Oct 2026']];

    main.innerHTML = `
      <div class="doc-layout">
        <article class="doc">
          <header class="title-block">
            <div class="tb-head">
              <p class="tb-kicker">${doc.group === 'formal' ? 'Formal document' : 'Reference annex'} · Anvil</p>
              <h1>${esc(doc.title)}</h1>
              ${doc.summary ? `<p class="tb-summary">${esc(doc.summary)}</p>` : ''}
            </div>
            <dl class="tb-cells">${cells.map(([k, v]) => `<div class="tb-cell"><dt>${k}</dt><dd>${k === 'Status' ? v : esc(v)}</dd></div>`).join('')}</dl>
          </header>
          <div class="prose">${doc.html}</div>
          <nav class="pager" aria-label="Previous and next document">
            ${prev ? `<a class="prev" href="#/doc/${prev.id}"><small>Previous</small><span>${esc(prev.short)} · ${esc(prev.title)}</span></a>` : ''}
            ${next ? `<a class="next" href="#/doc/${next.id}"><small>Next</small><span>${esc(next.short)} · ${esc(next.title)}</span></a>` : ''}
          </nav>
        </article>
        ${doc.headings.length ? `
        <aside class="toc" aria-label="On this page">
          <p class="toc-title">On this page</p>
          <ol>${doc.headings.map((h) => `<li><a class="depth-${h.depth}" href="#/doc/${doc.id}/${h.slug}" data-slug="${h.slug}">${esc(h.text)}</a></li>`).join('')}</ol>
        </aside>` : ''}
      </div>`;

    const prose = $('.prose', main);
    // The metadata lines under each formal title are shown in the title block instead.
    $$(':scope > p', prose).slice(0, 2).forEach((p) => { if (/Document ID:|Traces:/.test(p.textContent)) p.remove(); });
    linkIds(prose);
    addTableFilters(prose);
    renderMermaid(prose);
    watchHeadings(doc);
    requestAnimationFrame(() => scrollToAnchor(r.anchor));
  }

  // Requirement, test, diagram and document IDs become links or search shortcuts.
  const ID_RE = /\b(ANV-[A-Z]+-\d{3}|N?FR-[A-Z]+-\d\d|TC-[A-Z]+-\d\d|(?:UC|SD|AD|ST|CD|CP|DP|ER|CX|PM)-\d\d|UC-\d{1,2}|IR-\d{1,2}|DR-\d|ADR-\d{3}|RK-\d|CON-\d|ASM-\d|OBJ-\d|OI-\d)\b/g;
  const ID_TEST = new RegExp(ID_RE.source); // non-global copy: .test() on a /g regex keeps state between calls

  function linkIds(root) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: (n) => (n.parentElement.closest('pre, code, a, button, h1, h2, h3, h4, .ref-id') ? NodeFilter.FILTER_REJECT
        : ID_TEST.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP),
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    for (const node of nodes) {
      ID_RE.lastIndex = 0;
      const frag = document.createDocumentFragment();
      let last = 0;
      const text = node.nodeValue;
      for (const m of text.matchAll(ID_RE)) {
        frag.append(text.slice(last, m.index));
        frag.append(idElement(m[0]));
        last = m.index + m[0].length;
      }
      frag.append(text.slice(last));
      node.replaceWith(frag);
    }
  }

  function idElement(id) {
    const dia = diagramsByCode.get(id);
    const doc = docsByCode.get(id);
    if (dia || doc) {
      const a = document.createElement('a');
      a.className = 'ref-id' + (dia ? ' kind-diagram' : '');
      a.href = dia ? `#/diagram/${dia.name}` : `#/doc/${doc.id}`;
      a.title = dia ? `${dia.kind} diagram: ${dia.title}` : doc.title;
      a.textContent = id;
      return a;
    }
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'ref-id';
    b.title = `Find every mention of ${id}`;
    b.textContent = id;
    b.addEventListener('click', () => openSearch(id));
    return b;
  }

  function addTableFilters(root) {
    $$('.table-wrap', root).forEach((wrap, i) => {
      const rows = $$('tbody tr', wrap);
      if (rows.length < 12) return;
      const tools = document.createElement('div');
      tools.className = 'table-tools';
      const id = `table-filter-${i}`;
      tools.innerHTML = `<input id="${id}" type="search" placeholder="Filter ${rows.length} rows…" aria-label="Filter table rows"><span aria-live="polite">${rows.length} rows</span>`;
      wrap.before(tools);
      const input = $('input', tools);
      const count = $('span', tools);
      input.addEventListener('input', () => {
        const q = input.value.trim().toLowerCase();
        let shown = 0;
        rows.forEach((tr) => {
          const hit = !q || tr.textContent.toLowerCase().includes(q);
          tr.hidden = !hit;
          if (hit) shown++;
        });
        count.textContent = q ? `${shown} of ${rows.length} rows` : `${rows.length} rows`;
      });
    });
  }

  function watchHeadings(doc) {
    const links = new Map($$('.toc a', main).map((a) => [a.dataset.slug, a]));
    if (!links.size || !('IntersectionObserver' in window)) return;
    spy = new IntersectionObserver((entries) => {
      const visible = entries.filter((e) => e.isIntersecting).sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
      if (!visible) return;
      links.forEach((a) => a.classList.remove('active'));
      links.get(visible.target.id)?.classList.add('active');
    }, { rootMargin: '-80px 0px -70% 0px' });
    doc.headings.forEach((h) => { const el = document.getElementById(h.slug); if (el) spy.observe(el); });
  }

  // Mermaid sketches in the reference annexes render with Mermaid from cdnjs; offline they stay as source text.
  let mermaidLoading = null;
  function renderMermaid(root) {
    const nodes = $$('pre.mermaid', root);
    if (!nodes.length) return;
    mermaidLoading = mermaidLoading || new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = 'https://cdnjs.cloudflare.com/ajax/libs/mermaid/11.4.0/mermaid.min.js';
      s.onload = resolve;
      s.onerror = reject;
      document.head.append(s);
    });
    mermaidLoading.then(() => {
      window.mermaid.initialize({ startOnLoad: false, securityLevel: 'strict', theme: isDark() ? 'dark' : 'default', fontFamily: 'IBM Plex Sans, sans-serif' });
      return window.mermaid.run({ nodes });
    }).catch(() => { /* offline or blocked: the diagram source stays readable */ });
  }

  /* ------------------------------------------------------------------ diagrams */

  function renderGallery(r) {
    const kinds = [...new Set(diagrams.map((d) => d.kind))];
    const shown = r.kind ? diagrams.filter((d) => d.kind === r.kind) : diagrams;
    main.innerHTML = `
      <div class="page">
        <header class="page-head">
          <p class="eyebrow">ANV-DIA-001 · UML 2.5 and C4</p>
          <h1>Diagram catalogue</h1>
          <p>Every diagram referenced by the formal documents. Select one to zoom, pan, see which documents use it, and read its source.</p>
        </header>
        <div class="filters" role="group" aria-label="Filter by diagram type">
          <button class="filter" type="button" data-kind="" aria-pressed="${!r.kind}">All<span>${diagrams.length}</span></button>
          ${kinds.map((k) => `<button class="filter" type="button" data-kind="${esc(k)}" aria-pressed="${r.kind === k}">${esc(k)}<span>${diagrams.filter((d) => d.kind === k).length}</span></button>`).join('')}
        </div>
        <div class="gallery">
          ${shown.map((d) => `
            <a class="dia-card" href="#/diagram/${d.name}">
              <span class="dia-thumb"><img src="diagrams/${d.name}.svg" alt="" loading="lazy" width="${d.width}" height="${d.height}"></span>
              <span class="dia-meta"><span class="dia-code">${d.code} · ${esc(d.kind)}</span><b>${esc(d.title)}</b></span>
            </a>`).join('')}
        </div>
      </div>`;
    $$('.filter', main).forEach((b) => b.addEventListener('click', () => {
      location.hash = b.dataset.kind ? `#/diagrams?kind=${encodeURIComponent(b.dataset.kind)}` : '#/diagrams';
    }));
    window.scrollTo(0, 0);
  }

  function renderDiagram(r) {
    const d = diagramsByName.get(r.name);
    const i = diagrams.indexOf(d);
    const prev = diagrams[i - 1];
    const next = diagrams[i + 1];
    main.innerHTML = `
      <div class="page">
        <div class="viewer-head">
          <div>
            <p class="eyebrow"><a href="#/diagrams">Diagrams</a> · ${d.code} · ${esc(d.kind)}</p>
            <h1>${esc(d.title)}</h1>
          </div>
          <div class="viewer-tools" role="group" aria-label="Zoom">
            <button class="btn" type="button" data-zoom="out" aria-label="Zoom out">−</button>
            <span class="zoom-level" id="zoom-level">100%</span>
            <button class="btn" type="button" data-zoom="in" aria-label="Zoom in">+</button>
            <button class="btn" type="button" data-zoom="fit">Fit</button>
            <button class="btn" type="button" data-zoom="actual">1:1</button>
          </div>
        </div>
        <div class="viewer" id="viewer" tabindex="0" aria-label="${esc(d.full)}. Drag to pan, scroll to zoom.">
          <img src="diagrams/${d.name}.svg" alt="${esc(d.full)}" width="${d.width}" height="${d.height}" draggable="false">
          <span class="viewer-hint">Drag to pan · scroll or +/− to zoom · 0 to fit</span>
        </div>
        <div class="viewer-grid">
          <details class="source">
            <summary>Diagram source (Mermaid) · docs/diagrams/src/${esc(d.name)}.mmd</summary>
            <div class="code-wrap"><pre><code>${esc(d.source)}</code></pre></div>
          </details>
          <div class="viewer-side">
            <div>
              <h2>Used in</h2>
              ${d.usedIn.length ? `<ul>${d.usedIn.map((id) => `<li><a href="#/doc/${id}">${esc(docsById.get(id).short)} · ${esc(docsById.get(id).title)}</a></li>`).join('')}</ul>` : '<p>Diagram catalogue only.</p>'}
            </div>
            <div>
              <h2>Files</h2>
              <ul><li><a href="diagrams/${d.name}.svg" target="_blank" rel="noopener">Open SVG in a new tab</a></li></ul>
            </div>
            <div class="dia-pager">
              ${prev ? `<a href="#/diagram/${prev.name}">← ${prev.code}</a>` : '<span></span>'}
              ${next ? `<a href="#/diagram/${next.name}">${next.code} →</a>` : ''}
            </div>
          </div>
        </div>
      </div>`;
    setupViewer($('#viewer'), d);
    window.scrollTo(0, 0);
  }

  /** Pan and zoom for one diagram: pointer drag, wheel zoom around the cursor, buttons and keys. */
  function setupViewer(viewer, d) {
    const img = $('img', viewer);
    const label = $('#zoom-level');
    let scale = 1, x = 0, y = 0;

    const apply = () => {
      img.style.transform = `translate(${x}px, ${y}px) scale(${scale})`;
      label.textContent = `${Math.round(scale * 100)}%`;
    };
    const fit = () => {
      const r = viewer.getBoundingClientRect();
      scale = Math.min((r.width - 32) / d.width, (r.height - 32) / d.height, 2);
      x = (r.width - d.width * scale) / 2;
      y = (r.height - d.height * scale) / 2;
      apply();
    };
    const zoomAt = (factor, cx, cy) => {
      const next = Math.min(6, Math.max(0.05, scale * factor));
      x = cx - (cx - x) * (next / scale);
      y = cy - (cy - y) * (next / scale);
      scale = next;
      apply();
    };
    const center = () => { const r = viewer.getBoundingClientRect(); return [r.width / 2, r.height / 2]; };

    viewer.addEventListener('wheel', (e) => {
      e.preventDefault();
      const r = viewer.getBoundingClientRect();
      zoomAt(e.deltaY < 0 ? 1.15 : 1 / 1.15, e.clientX - r.left, e.clientY - r.top);
    }, { passive: false });

    let drag = null;
    viewer.addEventListener('pointerdown', (e) => {
      drag = { px: e.clientX, py: e.clientY, x, y };
      viewer.setPointerCapture(e.pointerId);
      viewer.classList.add('dragging');
    });
    viewer.addEventListener('pointermove', (e) => {
      if (!drag) return;
      x = drag.x + e.clientX - drag.px;
      y = drag.y + e.clientY - drag.py;
      apply();
    });
    const end = () => { drag = null; viewer.classList.remove('dragging'); };
    viewer.addEventListener('pointerup', end);
    viewer.addEventListener('pointercancel', end);

    viewer.addEventListener('keydown', (e) => {
      const step = 40;
      if (e.key === '+' || e.key === '=') zoomAt(1.2, ...center());
      else if (e.key === '-') zoomAt(1 / 1.2, ...center());
      else if (e.key === '0') fit();
      else if (e.key === 'ArrowLeft') { x += step; apply(); }
      else if (e.key === 'ArrowRight') { x -= step; apply(); }
      else if (e.key === 'ArrowUp') { y += step; apply(); }
      else if (e.key === 'ArrowDown') { y -= step; apply(); }
      else return;
      e.preventDefault();
    });

    $$('[data-zoom]').forEach((b) => b.addEventListener('click', () => {
      const z = b.dataset.zoom;
      if (z === 'in') zoomAt(1.25, ...center());
      else if (z === 'out') zoomAt(1 / 1.25, ...center());
      else if (z === 'fit') fit();
      else { const [cx, cy] = center(); scale = 1; x = cx - d.width / 2; y = cy - d.height / 2; apply(); }
    }));

    fit();
    window.addEventListener('resize', fit, { once: true });
  }

  /* ------------------------------------------------------------------ search */

  const dialog = $('#search-dialog');
  const input = $('#search-input');
  const results = $('#search-results');
  const hint = $('#search-hint');
  let hits = [];
  let selected = 0;
  let lastFocus = null;

  function openSearch(query = '') {
    lastFocus = document.activeElement;
    dialog.hidden = false;
    input.value = query;
    runSearch();
    input.focus();
    input.select();
  }
  function closeSearch() {
    dialog.hidden = true;
    if (lastFocus && document.contains(lastFocus)) lastFocus.focus();
  }

  function runSearch() {
    const q = input.value.trim().toLowerCase();
    const terms = q.split(/\s+/).filter(Boolean);
    if (q.length < 2) {
      hits = [];
      results.innerHTML = '';
      hint.textContent = 'Type at least two characters. Use ↑ ↓ to move and Enter to open.';
      return;
    }
    const scored = [];
    for (const s of DATA.search) {
      const head = s.heading.toLowerCase();
      const body = s.text.toLowerCase();
      if (!terms.every((t) => head.includes(t) || body.includes(t))) continue;
      let score = 0;
      for (const t of terms) {
        if (head.includes(t)) score += 12;
        score += Math.min(8, body.split(t).length - 1);
      }
      if (body.includes(q)) score += 6;
      if (docsById.get(s.doc).group === 'formal') score += 2;
      scored.push({ s, score });
    }
    for (const d of diagrams) {
      const hay = `${d.code} ${d.kind} ${d.title}`.toLowerCase();
      if (terms.every((t) => hay.includes(t))) scored.push({ dia: d, score: 15 });
    }
    scored.sort((a, b) => b.score - a.score);
    hits = scored.slice(0, 40);
    selected = 0;
    hint.textContent = hits.length ? `${scored.length} result${scored.length === 1 ? '' : 's'}${scored.length > hits.length ? `, showing the best ${hits.length}` : ''}.` : `No results for “${input.value.trim()}”. Try a requirement ID like FR-CI-08, or a single word.`;
    results.innerHTML = hits.map((h, i) => {
      if (h.dia) {
        return `<li role="option" id="sr-${i}" aria-selected="${i === 0}"><a href="#/diagram/${h.dia.name}"><span class="sr-where">Diagram · ${h.dia.code} · ${esc(h.dia.kind)}</span><span class="sr-title">${highlight(esc(h.dia.title), terms)}</span></a></li>`;
      }
      const doc = docsById.get(h.s.doc);
      const href = `#/doc/${doc.id}${h.s.anchor ? '/' + h.s.anchor : ''}`;
      return `<li role="option" id="sr-${i}" aria-selected="${i === 0}"><a href="${href}"><span class="sr-where">${esc(doc.short)} · ${esc(doc.title)}</span><span class="sr-title">${highlight(esc(h.s.heading), terms)}</span><span class="sr-snippet">${snippet(h.s.text, terms)}</span></a></li>`;
    }).join('');
    syncSelection();
  }

  function snippet(text, terms) {
    const lower = text.toLowerCase();
    const at = Math.max(0, Math.min(...terms.map((t) => { const i = lower.indexOf(t); return i < 0 ? Infinity : i; })));
    const start = Number.isFinite(at) ? Math.max(0, at - 60) : 0;
    const piece = text.slice(start, start + 200);
    return (start > 0 ? '…' : '') + highlight(esc(piece), terms) + (start + 200 < text.length ? '…' : '');
  }

  function highlight(html, terms) {
    const safe = terms.map((t) => esc(t).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).filter(Boolean);
    if (!safe.length) return html;
    return html.replace(new RegExp(`(${safe.join('|')})`, 'gi'), '<mark>$1</mark>');
  }

  function syncSelection() {
    $$('li', results).forEach((li, i) => li.setAttribute('aria-selected', String(i === selected)));
    const li = $(`#sr-${selected}`);
    if (li) { li.scrollIntoView({ block: 'nearest' }); input.setAttribute('aria-activedescendant', li.id); }
  }

  input.addEventListener('input', runSearch);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown') { selected = Math.min(hits.length - 1, selected + 1); syncSelection(); e.preventDefault(); }
    else if (e.key === 'ArrowUp') { selected = Math.max(0, selected - 1); syncSelection(); e.preventDefault(); }
    else if (e.key === 'Enter') { const a = $(`#sr-${selected} a`); if (a) { closeSearch(); location.hash = a.getAttribute('href'); } e.preventDefault(); }
  });
  results.addEventListener('click', (e) => { if (e.target.closest('a')) closeSearch(); });
  dialog.addEventListener('click', (e) => { if (e.target === dialog) closeSearch(); });
  $('#search-btn').addEventListener('click', () => openSearch());

  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); dialog.hidden ? openSearch() : closeSearch(); }
    else if (e.key === '/' && dialog.hidden && !e.target.closest('input, textarea, [contenteditable]')) { e.preventDefault(); openSearch(); }
    else if (e.key === 'Escape') { if (!dialog.hidden) closeSearch(); else closeDrawer(); }
  });

  /* ------------------------------------------------------------------ theme + drawer */

  const THEMES = ['system', 'light', 'dark'];
  const themeBtn = $('#theme-btn');
  function storedTheme() { try { return localStorage.getItem('anvil-theme') || 'system'; } catch { return 'system'; } }
  function applyTheme(mode) {
    if (mode === 'system') document.documentElement.removeAttribute('data-theme');
    else document.documentElement.setAttribute('data-theme', mode);
    themeBtn.setAttribute('aria-label', `Theme: ${mode}. Change theme`);
    themeBtn.title = `Theme: ${mode}`;
  }
  function isDark() {
    const t = document.documentElement.getAttribute('data-theme');
    return t ? t === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
  }
  themeBtn.addEventListener('click', () => {
    const next = THEMES[(THEMES.indexOf(storedTheme()) + 1) % THEMES.length];
    try { localStorage.setItem('anvil-theme', next); } catch { /* storage unavailable: theme lasts for this visit */ }
    applyTheme(next);
  });

  const sidebar = $('#sidebar');
  const scrim = $('#scrim');
  const menuBtn = $('#menu-btn');
  function openDrawer() { sidebar.classList.add('open'); scrim.hidden = false; menuBtn.setAttribute('aria-expanded', 'true'); }
  function closeDrawer() { sidebar.classList.remove('open'); scrim.hidden = true; menuBtn.setAttribute('aria-expanded', 'false'); }
  menuBtn.addEventListener('click', () => (sidebar.classList.contains('open') ? closeDrawer() : openDrawer()));
  scrim.addEventListener('click', closeDrawer);

  /* ------------------------------------------------------------------ start */

  if (storedTheme() !== 'system') applyTheme(storedTheme());
  renderSidebar();
  window.addEventListener('hashchange', route);
  route();
})();
